const CACHE_NAME='daodejing-v2';
const STATIC_CACHE='daodejing-static-v2';
const API_CACHE='daodejing-api-v1';
const IMAGE_CACHE='daodejing-images-v1';const STATIC_ASSETS=['/','/daodejing/','/static/css/style.css','/static/js/main.js','/static/js/modules/theme.js','/static/js/modules/sidebar.js','/static/js/modules/music.js','/static/js/modules/shortcuts.js','/static/js/modules/bookmark.js','/static/js/modules/reading-progress.js','https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css','https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js'];self.addEventListener('install',(event)=>{console.log('[SW] 安装 Service Worker');event.waitUntil(caches.open(STATIC_CACHE).then((cache)=>{console.log('[SW] 缓存静态资源');return cache.addAll(STATIC_ASSETS.map(url=>new Request(url,{cache:'reload'}))).catch(err=>{console.log('[SW] 部分资源缓存失败:',err);});}));self.skipWaiting();});self.addEventListener('activate',(event)=>{console.log('[SW] 激活 Service Worker');event.waitUntil(caches.keys().then((cacheNames)=>{return Promise.all(cacheNames.map((cacheName)=>{if(!['daodejing-v2','daodejing-static-v2','daodejing-api-v1','daodejing-images-v1'].includes(cacheName)){console.log('[SW] 删除旧缓存:',cacheName);return caches.delete(cacheName);}}));}));self.clients.claim();});self.addEventListener('fetch',(event)=>{const{request}=event;const url=new URL(request.url);if(url.origin!==self.location.origin){if(url.hostname==='cdn.jsdelivr.net'){event.respondWith(fetch(request).catch(()=>caches.match(request)));}
return;}
if(url.pathname.startsWith('/api/')){event.respondWith(fetch(request).catch(()=>{return caches.match(request).then(response=>{return response||new Response(JSON.stringify({error:'网络不可用'}),{headers:{'Content-Type':'application/json'}});});}));return;}
if(url.pathname.startsWith('/static/')){event.respondWith(caches.match(request).then((response)=>{if(response){return response;}
return fetch(request).then((response)=>{if(response.status===200){const responseClone=response.clone();caches.open(STATIC_CACHE).then((cache)=>{cache.put(request,responseClone);});}
return response;});}));return;}
event.respondWith(fetch(request).catch(()=>{return caches.match(request).then((response)=>{if(response){return response;}
if(request.mode==='navigate'){return caches.match('/daodejing/');}
return new Response('离线状态下无法访问此资源',{status:503,statusText:'Service Unavailable',headers:new Headers({'Content-Type':'text/plain'})});});}));});self.addEventListener('message',(event)=>{if(event.data&&event.data.type==='SKIP_WAITING'){self.skipWaiting();}
if(event.data&&event.data.type==='CLEAR_CACHE'){event.waitUntil(caches.keys().then((cacheNames)=>{return Promise.all(cacheNames.map((cacheName)=>caches.delete(cacheName)));}));}});
